#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    char* s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok* t) {
    while (t->pos < t->len && (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
           t->s[t->pos] == '\t' || t->s[t->pos] == '\n' || t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else if (t->s[t->pos] == '"') {
        t->pos++;
        while (t->pos < t->len && t->s[t->pos] != '"') t->pos++;
        if (t->pos < t->len) t->pos++;
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' &&
               t->s[t->pos] != ']' && t->s[t->pos] != '[') t->pos++;
    }
    int token_len = t->pos - start;
    char* token = (char*)malloc((size_t)token_len + 1);
    memcpy(token, t->s + start, (size_t)token_len);
    token[token_len] = '\0';
    return token;
}

static char* parse_string(Tok* t) {
    char* tok = nextToken(t);
    if (!tok) return NULL;
    if (tok[0] == '"') {
        int len = (int)strlen(tok);
        char* res = (char*)malloc((size_t)len - 1);
        memcpy(res, tok + 1, (size_t)len - 2);
        res[len - 2] = '\0';
        free(tok);
        return res;
    }
    return tok;
}

