int* movesToStamp(char* stamp, char* target, int* returnSize) {
    int m = (int)strlen(stamp);
    int n = (int)strlen(target);
    int windows = n - m + 1;

    int* made = (int*)calloc(windows * m, sizeof(int));
    int* madeCount = (int*)calloc(windows, sizeof(int));
    int* todo = (int*)calloc(windows * m, sizeof(int));
    int* todoCount = (int*)calloc(windows, sizeof(int));
    bool* erased = (bool*)calloc(n, sizeof(bool));
    int* queue = (int*)malloc(n * sizeof(int));
    int qHead = 0, qTail = 0;
    int* answer = (int*)malloc(n * sizeof(int));
    int answerCount = 0;

    for (int i = 0; i < windows; ++i) {
        for (int j = 0; j < m; ++j) {
            int p = i + j;
            if (target[p] == stamp[j])
                made[i * m + madeCount[i]++] = p;
            else
                todo[i * m + todoCount[i]++] = p;
        }
        if (todoCount[i] == 0) {
            answer[answerCount++] = i;
            for (int k = 0; k < madeCount[i]; ++k) {
                int p = made[i * m + k];
                if (!erased[p]) {
                    erased[p] = true;
                    queue[qTail++] = p;
                }
            }
        }
    }

    while (qHead < qTail) {
        int pos = queue[qHead++];
        int start = pos - m + 1;
        if (start < 0) start = 0;
        int end = pos;
        if (end > n - m) end = n - m;

        for (int i = start; i <= end; ++i) {
            bool found = false;
            for (int k = 0; k < todoCount[i]; ++k) {
                if (todo[i * m + k] == pos) {
                    todo[i * m + k] = todo[i * m + (--todoCount[i])];
                    found = true;
                    break;
                }
            }
            if (!found || todoCount[i] != 0) continue;

            answer[answerCount++] = i;
            for (int k = 0; k < madeCount[i]; ++k) {
                int p = made[i * m + k];
                if (!erased[p]) {
                    erased[p] = true;
                    queue[qTail++] = p;
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        if (!erased[i]) {
            free(made); free(madeCount); free(todo); free(todoCount);
            free(erased); free(queue); free(answer);
            *returnSize = 0;
            return NULL;
        }
    }

    for (int i = 0; i < answerCount / 2; ++i) {
        int tmp = answer[i];
        answer[i] = answer[answerCount - 1 - i];
        answer[answerCount - 1 - i] = tmp;
    }

    free(made); free(madeCount); free(todo); free(todoCount);
    free(erased); free(queue);
    *returnSize = answerCount;
    return answer;
}

int main() {
    char line[1000005];
    if (fgets(line, sizeof(line), stdin)) {
        int len = (int)strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }
        char* raw = (char*)malloc((size_t)len - 1);
        memcpy(raw, line + 1, (size_t)len - 2);
        raw[len - 2] = '\0';

        Tok tok = {raw, 0, (int)strlen(raw)};
        char* stamp = parse_string(&tok);
        char* target = parse_string(&tok);

        int returnSize = 0;
        int* result = movesToStamp(stamp, target, &returnSize);
        printf("[");
        for (int i = 0; i < returnSize; ++i) {
            if (i) printf(",");
            printf("%d", result[i]);
        }
        printf("]\n");

        free(result);
        free(stamp);
        free(target);
        free(raw);
    }
    return 0;
}

