class Solution {
public:
    vector<int> movesToStamp(string stamp, string target) {
        int m = stamp.size(), n = target.size();
        vector<vector<int>> made(n - m + 1);
        vector<unordered_set<int>> todo(n - m + 1);
        queue<int> q;
        vector<char> erased(n, false);
        vector<int> answer;

        for (int i = 0; i <= n - m; ++i) {
            for (int j = 0; j < m; ++j) {
                if (target[i + j] == stamp[j]) made[i].push_back(i + j);
                else todo[i].insert(i + j);
            }
            if (todo[i].empty()) {
                answer.push_back(i);
                for (int p : made[i]) {
                    if (!erased[p]) {
                        erased[p] = true;
                        q.push(p);
                    }
                }
            }
        }

        while (!q.empty()) {
            int pos = q.front();
            q.pop();
            int start = max(0, pos - m + 1);
            int end = min(n - m, pos);
            for (int i = start; i <= end; ++i) {
                auto it = todo[i].find(pos);
                if (it == todo[i].end()) continue;
                todo[i].erase(it);
                if (!todo[i].empty()) continue;
                answer.push_back(i);
                for (int p : made[i]) {
                    if (!erased[p]) {
                        erased[p] = true;
                        q.push(p);
                    }
                }
            }
        }

        for (char x : erased) if (!x) return {};
        reverse(answer.begin(), answer.end());
        return answer;
    }
};

