import java.io.*;
import java.util.*;

class Solution {
    public int[] movesToStamp(String stamp, String target) {
        int m = stamp.length(), n = target.length();
        List<int[]> made = new ArrayList<>();
        List<Set<Integer>> todo = new ArrayList<>();
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        boolean[] erased = new boolean[n];
        List<Integer> answer = new ArrayList<>();

        for (int i = 0; i <= n - m; i++) {
            List<Integer> madeList = new ArrayList<>();
            Set<Integer> todoSet = new HashSet<>();
            for (int j = 0; j < m; j++) {
                if (target.charAt(i + j) == stamp.charAt(j)) {
                    madeList.add(i + j);
                } else {
                    todoSet.add(i + j);
                }
            }
            int[] madeArray = new int[madeList.size()];
            for (int k = 0; k < madeList.size(); k++) madeArray[k] = madeList.get(k);
            made.add(madeArray);
            todo.add(todoSet);

            if (todoSet.isEmpty()) {
                answer.add(i);
                for (int p : madeArray) {
                    if (!erased[p]) {
                        erased[p] = true;
                        queue.add(p);
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            int pos = queue.remove();
            int start = Math.max(0, pos - m + 1);
            int end = Math.min(n - m, pos);
            for (int i = start; i <= end; i++) {
                if (!todo.get(i).remove(pos)) continue;
                if (!todo.get(i).isEmpty()) continue;
                answer.add(i);
                for (int p : made.get(i)) {
                    if (!erased[p]) {
                        erased[p] = true;
                        queue.add(p);
                    }
                }
            }
        }

        if (!allErased(erased)) return new int[0];
        int[] result = new int[answer.size()];
        for (int i = 0; i < answer.size(); i++) {
            result[i] = answer.get(answer.size() - 1 - i);
        }
        return result;
    }

    private boolean allErased(boolean[] erased) {
        for (boolean x : erased) if (!x) return false;
        return true;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        int[] cursor = {0};

        String stamp = readString(line, cursor);
        String target = readString(line, cursor);

        int[] result = new Solution().movesToStamp(stamp, target);
        System.out.println(Arrays.toString(result).replace(", ", ","));
    }

    private static String readString(String s, int[] cursor) {
        while (cursor[0] < s.length() && s.charAt(cursor[0]) != '"') cursor[0]++;
        cursor[0]++;
        int start = cursor[0];
        while (cursor[0] < s.length() && s.charAt(cursor[0]) != '"') cursor[0]++;
        String result = s.substring(start, cursor[0]);
        cursor[0]++;
        return result;
    }
}

