from collections import deque
from typing import List

class Solution:
    def movesToStamp(self, stamp: str, target: str) -> List[int]:
        m, n = len(stamp), len(target)
        windows = []
        queue = deque()
        erased = [False] * n
        answer = []

        for i in range(n - m + 1):
            made = set()
            todo = set()
            for j, ch in enumerate(stamp):
                if target[i + j] == ch:
                    made.add(i + j)
                else:
                    todo.add(i + j)
            windows.append([made, todo])

            if not todo:
                answer.append(i)
                for pos in made:
                    if not erased[pos]:
                        erased[pos] = True
                        queue.append(pos)

        while queue:
            pos = queue.popleft()
            start = max(0, pos - m + 1)
            end = min(n - m, pos) + 1
            for i in range(start, end):
                made, todo = windows[i]
                if pos not in todo:
                    continue
                todo.remove(pos)
                if todo:
                    continue
                answer.append(i)
                for p in made:
                    if not erased[p]:
                        erased[p] = True
                        queue.append(p)

        return answer[::-1] if all(erased) else []

if __name__ == "__main__":
    import json, sys
    args = json.loads(sys.stdin.readline())
    result = Solution().movesToStamp(args[0], args[1])
    print(json.dumps(result, separators=(",", ":")))

