'use strict';
const readline = require('readline');

var movesToStamp = function(stamp, target) {
    const m = stamp.length, n = target.length;
    const made = new Array(n - m + 1);
    const todo = new Array(n - m + 1);
    const queue = [];
    const erased = new Array(n).fill(false);
    const answer = [];

    for (let i = 0; i <= n - m; i++) {
        made[i] = [];
        todo[i] = [];
        for (let j = 0; j < m; j++) {
            if (target[i + j] === stamp[j]) made[i].push(i + j);
            else todo[i].push(i + j);
        }
        if (todo[i].length === 0) {
            answer.push(i);
            for (const p of made[i]) {
                if (!erased[p]) {
                    erased[p] = true;
                    queue.push(p);
                }
            }
        }
    }

    let head = 0;
    while (head < queue.length) {
        const pos = queue[head++];
        const start = Math.max(0, pos - m + 1);
        const end = Math.min(n - m, pos);
        for (let i = start; i <= end; i++) {
            const idx = todo[i].indexOf(pos);
            if (idx === -1) continue;
            todo[i].splice(idx, 1);
            if (todo[i].length !== 0) continue;
            answer.push(i);
            for (const p of made[i]) {
                if (!erased[p]) {
                    erased[p] = true;
                    queue.push(p);
                }
            }
        }
    }

    return erased.every(Boolean) ? answer.reverse() : [];
};

const rl = readline.createInterface({ input: process.stdin });
rl.on('line', line => {
    const args = JSON.parse(line.trim());
    const result = movesToStamp(args[0], args[1]);
    console.log(JSON.stringify(result));
    rl.close();
});
